import AppKit
import SwiftUI

struct AgentProviderIcon: View {
    let provider: AgentProvider

    init(_ provider: AgentProvider) {
        self.provider = provider
    }

    var body: some View {
        Group {
            if let image = AgentProviderIconAsset.image(for: provider) {
                Image(nsImage: image)
                    .resizable()
                    .interpolation(.high)
                    .scaledToFit()
            } else {
                Image(systemName: provider == .codex ? "terminal.fill" : "sparkles")
                    .resizable()
                    .scaledToFit()
                    .foregroundStyle(provider == .codex ? Color.indigo : Color.orange)
            }
        }
        .accessibilityHidden(true)
    }
}

private enum AgentProviderIconAsset {
    static func image(for provider: AgentProvider) -> NSImage? {
        let encoded = switch provider {
        case .codex: codex
        case .claude: claude
        }
        guard let data = Data(base64Encoded: encoded) else { return nil }
        return NSImage(data: data)
    }

    private static let codex = ""
    private static let claude = ""
}
